/* ------------------------------------------
   3. صور بديلة مرسومة (تظهر فقط عند غياب ملف الصورة)
   تُستخدم عبر onerror في وسم <img>.
------------------------------------------ */
const DEFS = `<defs>
  <linearGradient id="sh" x1="0" x2="1"><stop offset="0" stop-color="#fff" stop-opacity=".25"/><stop offset=".5" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".12"/></linearGradient>
</defs>`;

function bottleSVG(c) {
  return `
  <rect x="30" y="52" width="62" height="104" rx="3" fill="${c.box}"/>
  <rect x="30" y="52" width="62" height="104" rx="3" fill="url(#sh)"/>
  <circle cx="61" cy="96" r="9" fill="none" stroke="#C5A059" stroke-width="1.2"/>
  <path d="M56 99h10M61 90v14" stroke="#C5A059" stroke-width="1.2"/>
  <rect x="42" y="124" width="38" height="2" fill="#C5A059" opacity=".7"/>
  <rect x="102" y="84" width="48" height="72" rx="5" fill="#fff" fill-opacity=".55" stroke="#9c8f80" stroke-opacity=".5"/>
  <rect x="105" y="100" width="42" height="53" rx="2" fill="${c.liquid}" opacity=".95"/>
  <rect x="105" y="100" width="14" height="53" fill="#fff" opacity=".3"/>
  <rect x="114" y="72" width="24" height="14" rx="2" fill="${c.cap}"/>
  <rect x="120" y="84" width="12" height="4" fill="#cdbf9f"/>
  <circle cx="126" cy="122" r="5" fill="none" stroke="#C5A059" stroke-width="1"/>`;
}
function bagShape(x, y, w, h, fill) {
  return `<path d="M${x + w * .3} ${y} q${w * .2} -${h * .35} ${w * .4} 0" fill="none" stroke="#B08A45" stroke-width="3"/>
  <rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="${fill}"/>
  <rect x="${x}" y="${y}" width="${w}" height="${h}" rx="3" fill="url(#sh)"/>
  <circle cx="${x + w / 2}" cy="${y + h * .5}" r="${w * .12}" fill="none" stroke="#B08A45" stroke-width="1.4"/>`;
}
function boxShape(x, y, w, h, fill, bottles) {
  const step = (w - 28) / bottles.length;
  const items = bottles.map((b, i) => {
    const bx = x + 14 + i * step;
    return `<rect x="${bx + 3}" y="${y + 14}" width="14" height="${h - 28}" rx="2" fill="#E8DFC8" opacity=".9"/><rect x="${bx + 5}" y="${y + 8}" width="10" height="9" rx="1.5" fill="${b}"/>`;
  }).join("");
  return `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="4" fill="${fill}"/>${items}`;
}
const svgURI = (w, h, bg, body) =>
  "data:image/svg+xml;utf8," + encodeURIComponent(
    `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" preserveAspectRatio="xMidYMid slice">${DEFS}${bg ? `<rect width="${w}" height="${h}" fill="${bg}"/>` : ""}${body}</svg>`);

function fallbackProduct(c) {
  // neutral light stage + soft, realistic contact shadow under the bottle
  const shadow = `<defs><filter id="gs" x="-30%" y="-300%" width="160%" height="700%"><feGaussianBlur stdDeviation="4.5"/></filter></defs>
    <ellipse cx="92" cy="158" rx="68" ry="5.5" fill="#000" opacity=".26" filter="url(#gs)"/>`;
  return svgURI(180, 165, "#F7F7F7", shadow + bottleSVG(c));
}

function fallbackCategory(kind) {
  const bodies = {
    perfume: bottleSVG({ box: "#B8A88F", liquid: "#E7E3DA", cap: "#B08A45" }),
    burner: `<g transform="translate(0 6)"><path d="M90 40v14" stroke="#B08A45" stroke-width="3"/><path d="M62 98a28 28 0 0 1 56 0z" fill="#B88A3E"/><path d="M58 98h64l-8 30H66z" fill="#A6762E"/><path d="M70 128l-6 18M110 128l6 18M76 146h28" stroke="#A6762E" stroke-width="4" stroke-linecap="round"/><path d="M90 30c-8-8 8-14 0-24M104 36c-7-7 7-12 0-20" fill="none" stroke="#fff" stroke-opacity=".6" stroke-width="3"/></g>`,
    oud: `<g transform="rotate(-18 90 80)"><rect x="40" y="66" width="100" height="22" rx="5" fill="#6A4630"/><rect x="52" y="90" width="82" height="16" rx="5" fill="#7B5338"/><rect x="60" y="48" width="70" height="16" rx="5" fill="#5A3A28"/></g>`,
    bag: bagShape(52, 40, 76, 92, "#B8A583")
  };
  return svgURI(180, 150, "#E3D8C6", bodies[kind] || bodies.perfume);
}

function fallbackGift(kind) {
  const bodies = {
    boxBeige: `<path d="M30 70l30-22h100l-30 22z" fill="#D2BE96"/><path d="M30 70h130v50H30z" fill="#C9B287"/>${boxShape(34, 76, 122, 40, "#3a2d24", ["#C5A059", "#E8DFC8", "#C5A059"])}`,
    boxBurgundy: `<path d="M30 70l30-22h100l-30 22z" fill="#6c1f26"/><path d="M30 70h130v50H30z" fill="#7a2630"/>${boxShape(34, 76, 122, 40, "#4a141a", ["#B08A45", "#1b1714", "#B08A45"])}`,
    bag: bagShape(60, 36, 70, 84, "#B8A583")
  };
  return svgURI(190, 130, "#E9E0D1", bodies[kind] || bodies.bag);
}

function fallbackHero(b) {
  const stone = `<ellipse cx="200" cy="318" rx="130" ry="14" fill="#cdbfa8"/><path d="M110 318q0-18 90-18t90 18z" fill="#d9ccb7"/>`;
  if (b.scene === "gifts") {
    return svgURI(400, 340, null, `${stone}${bagShape(60, 80, 130, 200, "#B8A583")}<g transform="translate(205 150)">${boxShape(0, 0, 150, 130, "#7a2630", ["#B08A45", "#1b1714", "#B08A45"])}</g>`);
  }
  const p = storeData.bestSellers.find(x => x.name === b.product) || storeData.bestSellers[0];
  return svgURI(400, 340, null, `${stone}${bagShape(40, 50, 120, 210, "#B8A583")}<g transform="translate(130 20) scale(1.9)">${bottleSVG(p.colors)}</g><circle cx="125" cy="290" r="22" fill="#E9D8C2"/><circle cx="125" cy="290" r="9" fill="#d3b98f"/>`);
}

function fallbackStory() {
  return svgURI(520, 300, null, `<ellipse cx="260" cy="286" rx="230" ry="12" fill="#cdbfa8"/>
    ${bagShape(40, 80, 120, 200, "#B8A583")}
    <g transform="translate(150 150)">${boxShape(0, 0, 90, 130, "#B8A88F", ["#C5A059"])}</g>
    <g transform="translate(220 60) scale(1.5)">${bottleSVG({ box: "#B8A88F", liquid: "#E7E3DA", cap: "#B08A45" })}</g>
    <g transform="translate(330 100) scale(1.2)">${bottleSVG({ box: "#A9987E", liquid: "#9A5B22", cap: "#1b1714" })}</g>
    <g transform="translate(400 210)">${boxShape(0, 0, 110, 70, "#7a2630", ["#B08A45", "#1b1714"])}</g>`);
}

function logoSVG(cls = "") {
  return `<svg class="${cls}" viewBox="0 0 64 64" fill="none" stroke="#B08A45" stroke-width="1.5" stroke-linecap="round" aria-hidden="true">
    <circle cx="32" cy="34" r="25"/><path d="M32 4c-3 6-3 11 0 15 3-4 3-9 0-15zM26 14c-4 1-6 5-4 9 3-1 5-5 4-9zm12 0c4 1 6 5 4 9-3-1-5-5-4-9z"/>
    <text x="32" y="42" text-anchor="middle" font-family="Tajawal, sans-serif" font-weight="700" font-size="22" fill="#B08A45" stroke="none">DI</text></svg>`;
}

/* ------------------------------------------
   4. دوال مساعدة
------------------------------------------ */
const $ = sel => document.querySelector(sel);
const esc = s => String(s).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const fmtPrice = n => new Intl.NumberFormat("en-US").format(n);

// وسم صورة: يستخدم الصورة الحقيقية، وإن لم توجد يعرض البديل المرسوم
function img(src, fallback, alt, cls = "card-img", lazy = true) {
  return `<img src="${esc(src)}" alt="${esc(alt)}" class="${cls}"${lazy ? ' loading="lazy"' : ""} data-fallback="${fallback}" onerror="this.onerror=null;this.src=this.dataset.fallback">`;
}

/* ------------------------------------------
   5. دوال رندر الأقسام
------------------------------------------ */
/* Top bar marquee: .ticker-track holds two identical groups; each group repeats the message enough times to be at least as
   wide as the bar. style.css moves the track by -50% (one group) in a linear infinite loop, so there is never a gap.
   Only the very first copy is exposed to screen readers. */
function renderTopBar() {
  const bar = $("#top-bar");
  if (!bar) return;
  let track = bar.querySelector(".ticker-track");
  if (!track) { track = document.createElement("div"); track.className = "ticker-track"; track.id = "ticker-track"; bar.appendChild(track); }
  const t = storeData.topBar;
  const item = hidden => `<span class="ticker-item"${hidden ? ' aria-hidden="true"' : ""}><span>${esc(t.text)}</span>${icon(t.icon)}</span>`;
  let first = track.querySelector(".ticker-item");
  if (!first) { track.innerHTML = `<div class="ticker-group">${item(false)}</div>`; first = track.querySelector(".ticker-item"); }
  const oneW = first.getBoundingClientRect().width || 400;
  const n = Math.max(1, Math.ceil(bar.clientWidth / oneW));          // copies per group: group width >= bar width
  if (track.dataset.n === String(n)) return;                          // nothing to rebuild
  track.dataset.n = String(n);
  const copies = Array.from({ length: n }, (_, i) => item(i > 0)).join("");
  track.innerHTML = `<div class="ticker-group">${copies}</div><div class="ticker-group" aria-hidden="true">${Array.from({ length: n }, () => item(true)).join("")}</div>`;
}

function renderHeader() {
  // اربط صورة الهيدر المكتوبة في index.html بالشعار المضمّن (يتجاوز أي مشكلة مسار أو كاش)
  document.querySelectorAll("#logo .brand-logo, #logo .brand-logo-shine").forEach(i => { i.src = LOGO_DATA; });
  // الشعار مكتوب مباشرة في index.html (img.brand-logo)؛ عند تعذر تحميل الصورة نستبدلها بالشعار المرسوم ويبقى اسم المتجر ظاهراً
  const logo = $("#logo"), brandImg = logo && logo.querySelector(".brand-logo");
  const useFallback = () => { const m = logo.querySelector(".logo-mark"); if (m) m.outerHTML = logoSVG(); };   // نص الاسم يبقى ظاهراً دائماً
  if (brandImg) {
    if (brandImg.complete && brandImg.naturalWidth === 0) useFallback();
    else brandImg.addEventListener("error", useFallback, { once: true });
  }
  $("#nav-list").innerHTML = storeData.nav.map(n =>
    `<li><a href="${esc(n.href)}"${n.active ? ' class="active" aria-current="page"' : ""}>${esc(n.label)}</a></li>`).join("");
  $("#search-btn").innerHTML = icon("search");
  $("#account-btn").innerHTML = icon("user");
  $("#cart-btn").insertAdjacentHTML("afterbegin", icon("bag"));
  $("#menu-toggle").innerHTML = icon("menu");
}

let heroIndex = 0, heroTimer;
function renderHero() {
  // منطق شرطي خاص بالبانر فقط (يعادل في سلة: {% if slides and slides|length > 0 %}).
  // لا علاقة له بشعار الهيدر أو الفوتر لأنهما يُرسمان في renderHeader / renderFooter.
  const list = Array.isArray(storeData.banners) ? storeData.banners.filter(Boolean) : [];
  const section = $(".hero-section");
  if (!list.length) {                       // لا توجد شرائح: أخفِ البانر وشعاره بالكامل
    clearInterval(heroTimer);
    $("#hero-slides").innerHTML = "";
    $("#hero-dots").innerHTML = "";
    if (section) section.hidden = true;
    return;
  }
  if (section) section.hidden = false;
  const multi = list.length > 1;            // الأسهم والنقاط تظهر فقط عند وجود أكثر من شريحة
  $("#hero-next").hidden = $("#hero-prev").hidden = $("#hero-dots").hidden = !multi;
  $("#hero-slides").innerHTML = list.map((b, i) => `
    <article class="hero-slide${i === 0 ? " is-active" : ""}" role="group" aria-roledescription="slide" aria-label="${i + 1} / ${list.length}">
      <div class="hero-art">${img(b.image, fallbackHero(b), b.title, "hero-img", false)}</div>
      <div class="hero-copy">
        <img class="hero-logo hero-logo-img" src="${esc(storeData.brand.logo)}" alt="" width="640" height="793" decoding="async" onerror="this.onerror=null;this.outerHTML=logoSVG('hero-logo')">
        <p class="hero-brand">${esc(storeData.brand.name)}</p>
        <h1 class="hero-title">${esc(b.title)}</h1>
        <p class="hero-text">${esc(b.text)}</p>
        <a class="btn" href="${esc(b.cta.href)}">${esc(b.cta.label)}</a>
      </div>
    </article>`).join("");
  $("#hero-next").innerHTML = icon("chevL");   // "<" على اليسار
  $("#hero-prev").innerHTML = icon("chevR");   // ">" على اليمين
  $("#hero-dots").innerHTML = list.map((b, i) =>
    `<button class="dot" role="tab" aria-selected="${i === 0}" aria-label="الشريحة ${i + 1}" data-i="${i}"></button>`).join("");
}
function showSlide(i) {
  const slides = document.querySelectorAll(".hero-slide");
  const dots = document.querySelectorAll(".dot");
  if (!slides.length) return;
  heroIndex = (i + slides.length) % slides.length;
  slides.forEach((s, k) => s.classList.toggle("is-active", k === heroIndex));
  dots.forEach((d, k) => d.setAttribute("aria-selected", k === heroIndex));
}
function startHeroAuto() {
  clearInterval(heroTimer);
  if (document.querySelectorAll(".hero-slide").length < 2) return;
  if (matchMedia("(prefers-reduced-motion: reduce)").matches) return;
  heroTimer = setInterval(() => showSlide(heroIndex + 1), 4500);
}

