/* Royal Assembly Motion: يضيف طبقات الحلقة والحروف والزهرة لكل .logo-mark (الهيدر والفوتر)
   الطبقات هي نفس صورة الشعار مقصوصة بخرائط المناطق، فتكون اللقطة النهائية مطابقة للأصل. */
function upgradeLogoMarks() {
  const root = document.documentElement.style;
  Object.entries(LOGO_MASKS).forEach(([k, v]) => root.setProperty(`--m-${k}`, `url("${v}")`));
  document.querySelectorAll(".logo-mark").forEach(mark => {
    if (mark.querySelector(".brand-logo-layer")) return;
    const base = mark.querySelector(".brand-logo");
    const shine = mark.querySelector(".brand-logo-shine");
    if (!base) return;
    ["ring", "letters", "flower"].forEach(k => {
      const l = document.createElement("img");
      l.className = `brand-logo-layer layer-${k}`;
      l.src = base.src; l.alt = ""; l.setAttribute("aria-hidden", "true");
      l.width = 640; l.height = 793; l.decoding = "async";
      mark.insertBefore(l, shine || null);
    });
  });
}

/* HD logo
   1) resolveHDLogo(): the embedded PNG (512x634) is only the last resort. The first file that loads from this list wins:
        logo.svg (vector, sharp at any size / zoom) > logo-hd.png > long.png.
      Raster files are accepted only if they are at least as large as the embedded copy. Every .logo-mark and the hero logo
      are switched to it, and each mark is tagged data-kind="svg" | "raster" (style.css uses that for image-rendering).
   2) sharpenLogos(): for BITMAP logos only, pre-scale once to the exact device-pixel size (step-down halving, high-quality
      smoothing) so thin lines land 1:1 on screen pixels. Re-run on resize / zoom. Vector logos are left to the browser. */
const LOGO_CANDIDATES = ["logo.svg", "logo-hd.png", "long.png"];

function applyLogoSource(url, kind) {
  document.querySelectorAll(".logo-mark, .hero-logo-img").forEach(el => {
    el.dataset.kind = kind; el.dataset.srcFull = url; delete el.dataset.sharpH;
    (el.classList.contains("logo-mark") ? el.querySelectorAll("img") : [el]).forEach(i => { i.src = url; });
  });
  storeData.brand.logo = url;                    // later renders (slider, footer) reuse the HD file
  sharpenLogos();
}

function resolveHDLogo() {
  const embeddedW = 512;
  const tryNext = i => {
    if (i >= LOGO_CANDIDATES.length) return;     // keep the embedded copy
    const url = LOGO_CANDIDATES[i], isSvg = /\.svg(\?|$)/i.test(url), probe = new Image();
    probe.onload = () => {
      if (isSvg || probe.naturalWidth >= embeddedW) applyLogoSource(url, isSvg ? "svg" : "raster");
      else tryNext(i + 1);
    };
    probe.onerror = () => tryNext(i + 1);
    probe.src = url;
  };
  tryNext(0);
}

/* Pre-scale `url` to exactly h device pixels tall (step-down halving + high-quality smoothing). Cached per url+height,
   so header, footer and hero decode the big file only once per size. Resolves with a data URL (or the original if it is already small). */
const _logoScaleCache = new Map();
function scaledLogo(url, h) {
  const key = (url.startsWith("data:") ? "embedded:" + url.length : url) + "|" + h;
  if (_logoScaleCache.has(key)) return _logoScaleCache.get(key);
  const p = new Promise(resolve => {
    const full = new Image();
    full.onload = () => {
      if (full.naturalHeight <= h * 1.05) return resolve(url);
      const th = h, tw = Math.round(h * full.naturalWidth / full.naturalHeight);
      let src = full, cw = full.naturalWidth, ch = full.naturalHeight;
      const step = (w, hh) => {
        const c = document.createElement("canvas"); c.width = w; c.height = hh;
        const x = c.getContext("2d"); x.imageSmoothingEnabled = true; x.imageSmoothingQuality = "high";
        x.drawImage(src, 0, 0, w, hh); src = c; cw = w; ch = hh;
      };
      try {
        while (ch / 2 > th) step(Math.round(cw / 2), Math.round(ch / 2));
        step(tw, th);
        resolve(src.toDataURL("image/png"));
      } catch (err) { resolve(url); }
    };
    full.onerror = () => resolve(url);
    full.src = url;
  });
  _logoScaleCache.set(key, p);
  return p;
}

function sharpenLogos() {
  const dpr = Math.max(1, window.devicePixelRatio || 1);
  document.querySelectorAll(".logo-mark, .hero-logo-img").forEach(el => {
    const isMark = el.classList.contains("logo-mark");
    const imgs = isMark ? Array.from(el.querySelectorAll("img")) : [el];
    if (!imgs.length || (isMark && !el.querySelector(".brand-logo"))) return;
    if (!el.dataset.kind) el.dataset.kind = "raster";
    if (el.dataset.kind === "svg") return;                   // vector: always crisp
    const h = Math.round(el.offsetHeight * dpr);            // offsetHeight ignores hover transforms
    if (!h || el.dataset.sharpH === String(h)) return;
    if (!el.dataset.srcFull) el.dataset.srcFull = imgs[0].src;
    const token = el.dataset.srcFull;
    scaledLogo(token, h).then(out => {
      if (el.dataset.srcFull !== token) return;              // a newer source was applied meanwhile
      imgs.forEach(i => { i.src = out; });
      el.dataset.sharpH = String(h);
    });
  });
}

/* Footer brand: make "DOKHOON IRIS", the tagline and the icon row ONE justified box.
   The tagline's rendered width is the reference. The title's font-size and letter-spacing are fitted so its visible
   width equals it (edge to edge); the icon row already stretches to the same width via CSS (space-between). */
function fitFooterBrand() {
  const name = document.querySelector(".footer-brand .logo-text");
  const tag  = document.querySelector(".footer-brand .footer-tag");
  if (!name || !tag) return;
  const r = document.createRange(); r.selectNodeContents(tag);
  const target = r.getBoundingClientRect().width;               // exact width of the tagline text
  if (!target) return;
  name.style.fontSize = ""; name.style.letterSpacing = "";
  const measure = () => { const rr = document.createRange(); rr.selectNodeContents(name); return rr.getBoundingClientRect().width; };
  const chars = [...name.textContent].length;
  const cs = getComputedStyle(name);
  // 1) pick the font-size that fills the width with generous (.12em) tracking, within sane limits
  name.style.letterSpacing = ".12em";
  const fs0 = parseFloat(cs.fontSize), w0 = measure() - parseFloat(cs.letterSpacing);   // trailing tracking is invisible
  const fs = Math.max(18, Math.min(44, fs0 * target / w0));
  name.style.fontSize = fs + "px";
  // 2) fine-tune with letter-spacing so the visible width matches to the pixel
  name.style.letterSpacing = "0px";
  const base = measure();
  name.style.letterSpacing = Math.max(0, (target - base) / (chars - 1)) + "px";
}

function renderAll() {
  renderTopBar();
  renderHeader();
  renderHero();
  renderFeatures();
  renderCategories();
  renderProducts();
  renderGiftSets();
  renderBrandStory();
  renderPolicies();
  renderFooter();
  upgradeLogoMarks();
  sharpenLogos();
  resolveHDLogo();
  fitFooterBrand();
}

/* ------------------------------------------
   6. تحميل البيانات من الـ API (اختياري)
------------------------------------------ */
async function loadStoreData() {
  if (!API_BASE) return; // لم يتم ربط الـ Backend بعد
  try {
    const res = await fetch(API_BASE + ENDPOINTS.store, { headers: { Accept: "application/json" } });
    if (!res.ok) throw new Error(res.status);
    Object.assign(storeData, await res.json());
    /* أو جلب كل قسم على حدة:
       storeData.banners     = await (await fetch(API_BASE + ENDPOINTS.banners)).json();
       storeData.categories  = await (await fetch(API_BASE + ENDPOINTS.categories)).json();
       storeData.bestSellers = await (await fetch(API_BASE + ENDPOINTS.bestSellers)).json();
       storeData.giftSets    = await (await fetch(API_BASE + ENDPOINTS.giftSets)).json(); */
  } catch (err) {
    console.warn("تعذر الاتصال بالـ API، سيتم استخدام البيانات المحلية:", err);
  }
}

/* ------------------------------------------
   7. التحكم بالسلة
------------------------------------------ */
let cartCount = 0;

async function addToCart(productId) {
  const product = storeData.bestSellers.find(p => p.id === Number(productId));
  if (!product) return;
  cartCount++;
  updateCartBadge(true);
  showToast(`تمت إضافة ${product.name} إلى سلة التسوق`);

  /* ربط الـ Backend: حفظ السلة في الخادم
     await fetch(API_BASE + ENDPOINTS.cartAdd, {
       method: "POST",
       headers: { "Content-Type": "application/json" },
       credentials: "include",
       body: JSON.stringify({ productId, qty: 1 })
     });
     عند الفشل: تراجع عن cartCount وأظهر رسالة خطأ. */
}

function updateCartBadge(animate = false) {
  const badge = document.querySelector(".cart-count");
  if (!badge) return;
  badge.textContent = cartCount;
  badge.classList.toggle("has-items", cartCount > 0);
  if (animate) {
    badge.classList.remove("bump");
    void badge.offsetWidth;
    badge.classList.add("bump");
  }
}

let toastTimer;
function showToast(msg) {
  const t = $("#toast");
  t.textContent = msg;
  t.classList.add("show");
  clearTimeout(toastTimer);
  toastTimer = setTimeout(() => t.classList.remove("show"), 2200);
}

/* ------------------------------------------
   8. الأحداث
------------------------------------------ */
function bindEvents() {
  document.addEventListener("click", e => {
    const add = e.target.closest("[data-add]");
    if (add) addToCart(add.dataset.add);

    const dot = e.target.closest(".dot");
    if (dot) { showSlide(Number(dot.dataset.i)); startHeroAuto(); }

    const arrow = e.target.closest(".hero-arrow");
    if (arrow) { showSlide(heroIndex + (arrow.classList.contains("hero-next") ? 1 : -1)); startHeroAuto(); }
  });

  // قائمة الجوال
  const toggle = $("#menu-toggle"), nav = $("#nav-menu");
  toggle.addEventListener("click", () => {
    const open = nav.classList.toggle("open");
    toggle.setAttribute("aria-expanded", open);
  });
  nav.addEventListener("click", e => {
    if (e.target.closest("a")) { nav.classList.remove("open"); toggle.setAttribute("aria-expanded", false); }
  });

  // إيقاف التمرير التلقائي عند المرور بالماوس
  const hero = $(".hero-section");
  hero.addEventListener("mouseenter", () => clearInterval(heroTimer));
  hero.addEventListener("mouseleave", startHeroAuto);
  hero.addEventListener("focusin", () => clearInterval(heroTimer));

  // أزرار الهيدر (ربط الـ Backend لاحقاً)
  $("#search-btn").addEventListener("click", () => {
    // افتح نافذة البحث ثم: fetch(API_BASE + ENDPOINTS.search + encodeURIComponent(q))
    showToast("سيتم ربط البحث بالخادم");
  });
  $("#account-btn").addEventListener("click", () => {
    // وجّه المستخدم إلى ENDPOINTS.login أو افتح نافذة تسجيل الدخول
    showToast("سيتم ربط تسجيل الدخول بالخادم");
  });
  $("#cart-btn").addEventListener("click", () => {
    // افتح درج السلة أو انتقل لصفحة الدفع
    showToast(cartCount ? `لديك ${cartCount} منتج في السلة` : "سلة التسوق فارغة");
  });
}

/* ------------------------------------------
   8.1 حركات الأيقونات على اللمس
   على الحاسوب تعمل الحركة بالـ hover عبر CSS. على الجوال لا يوجد hover،
   فنضيف الصنف is-animating لمدة قصيرة عند اللمس.
------------------------------------------ */
function bindIconAnimations() {
  document.querySelectorAll(".feature, .policy, .top-bar").forEach(el => {
    el.addEventListener("pointerdown", e => {
      if (e.pointerType === "mouse") return;
      el.classList.add("is-animating");
      clearTimeout(el._animTimer);
      el._animTimer = setTimeout(() => el.classList.remove("is-animating"), 1800);
    });
  });
}

/* ------------------------------------------
   8.2 القائمة الرئيسية: نقل الخط الذهبي (active)
   - عند النقر: ينتقل الصنف active فوراً للرابط المضغوط.
   - عند التمرير: يتبع القسم الظاهر حالياً (Scroll-spy).
------------------------------------------ */
function bindNavActive() {
  const links = [...document.querySelectorAll("#nav-list a")];
  const items = links.map(a => {
    const h = a.getAttribute("href") || "";
    const target = h.length > 1 && h.startsWith("#") ? document.getElementById(h.slice(1)) : null;
    return { a, target };
  }).filter(i => i.target);
  if (!items.length) return;

  const setActive = link => {
    links.forEach(l => {
      const on = l === link;
      l.classList.toggle("active", on);
      if (on) l.setAttribute("aria-current", "page"); else l.removeAttribute("aria-current");
    });
  };
  const margin = el => parseFloat(getComputedStyle(el).scrollMarginTop) || 0;

  let pinned = null, clickLock = false, lockTimer, ticking = false;

  const sync = () => {
    const atBottom = innerHeight + scrollY >= document.documentElement.scrollHeight - 4;

    // الرابط المضغوط يبقى مفعّلاً طالما وصلنا لوجهته (حتى لو لم تكفِ الصفحة للتمرير أكثر)
    if (pinned) {
      const top = pinned.target.getBoundingClientRect().top;
      const m = margin(pinned.target);
      if (Math.abs(top - m) < 60 || (atBottom && top > m - 60 && top < innerHeight)) { setActive(pinned.a); return; }
      pinned = null;
    }

    let current = items[0], best = -Infinity;
    items.forEach(i => {
      const top = i.target.getBoundingClientRect().top;
      if (top <= margin(i.target) + 24 && top > best) { best = top; current = i; }
    });
    if (atBottom) current = items[items.length - 1];
    setActive(current.a);
  };

  const settle = () => {
    clearTimeout(lockTimer);
    lockTimer = setTimeout(() => { clickLock = false; sync(); }, 200);
  };

  document.querySelector("#nav-list").addEventListener("click", e => {
    const a = e.target.closest("a");
    const item = a && items.find(i => i.a === a);
    if (!item) return;
    pinned = item;
    setActive(a);
    clickLock = true;   // تجاهل التمرير الوسيط أثناء الانتقال السلس
    settle();
  });

  addEventListener("scroll", () => {
    if (clickLock) { settle(); return; }
    if (!ticking) { ticking = true; requestAnimationFrame(() => { ticking = false; sync(); }); }
  }, { passive: true });
  addEventListener("resize", sync);

  sync();
}

/* ------------------------------------------
   9. التشغيل عند اكتمال تحميل الصفحة
------------------------------------------ */
document.addEventListener("DOMContentLoaded", async () => {
  await loadStoreData();
  renderAll();
  bindEvents();
  bindIconAnimations();
  bindNavActive();
  updateCartBadge();
  startHeroAuto();
  // re-fit once the web fonts are ready and whenever the window changes size
  if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => { fitFooterBrand(); renderTopBar(); });
  let fitT; addEventListener("resize", () => { clearTimeout(fitT); fitT = setTimeout(() => { fitFooterBrand(); sharpenLogos(); renderTopBar(); }, 120); });
  sharpenLogos();   // layout is final now (CSS + fonts applied): make sure the logo matches the real box size
});

// ===== إضافات سلة =====
document.addEventListener('salla.cart.itemAdded', function(e) {
  var counter = document.querySelector('[data-cart-count]');
  if (counter) {
    counter.textContent = e.detail.cart.items_count;
    counter.classList.add('has-items', 'bump');
    setTimeout(function() { counter.classList.remove('bump'); }, 400);
  }
});

document.addEventListener('salla.cart.itemRemoved', function(e) {
  var counter = document.querySelector('[data-cart-count]');
  if (counter) {
    counter.textContent = e.detail.cart.items_count;
    if (e.detail.cart.items_count === 0) {
      counter.classList.remove('has-items');
    }
  }
});

salla.onReady(function() {
  var counter = document.querySelector('[data-cart-count]');
  if (counter && salla.cart.itemsCount > 0) {
    counter.classList.add('has-items');
  }
});
